import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Use simulator-scored search, with a critical-load rollout surrogate only
    for stable beam retention and DFS child ordering."""
    import re
    import time
    from functools import lru_cache

    try:
        import numpy as np
    except ImportError:
        np = None

    n = workload.num_txns
    if n <= 1:
        seq = list(range(n))
        return workload.get_opt_seq_cost(seq), seq

    @lru_cache(maxsize=None)
    def cost(seq):
        return workload.get_opt_seq_cost(list(seq))

    # Recover operation text and preserve both operation multiplicity and the
    # fact that one write makes all sharing on that item conflicting.
    values = None
    for value in getattr(workload, "__dict__", {}).values():
        if isinstance(value, (list, tuple)) and len(value) == n:
            values = list(value)
            break
        if isinstance(value, dict) and len(value) == n:
            ordered = [None] * n
            for key, txn in value.items():
                match = re.search(r"(\d+)$", str(key))
                if match and int(match.group(1)) < n:
                    ordered[int(match.group(1))] = txn
            if all(txn is not None for txn in ordered):
                values = ordered
                break

    access = [{} for _ in range(n)]
    if values is not None:
        for txn, text in enumerate(values):
            for mode, key in re.findall(r"([rRwW])\s*-\s*(\d+)", str(text)):
                key = int(key)
                count, writer = access[txn].get(key, (0, False))
                access[txn][key] = (count + 1, writer or mode.lower() == "w")

    @lru_cache(maxsize=None)
    def conflicts(i, j):
        if not access[i] or not access[j]:
            return True
        for key in access[i].keys() & access[j].keys():
            if access[i][key][1] or access[j][key][1]:
                return True
        return False

    def rollout(current_cost, remaining):
        """Estimate remaining conflict-chain pressure; never used for pruning."""
        loads = {}
        writers = {}
        for txn in remaining:
            for key, (count, writer) in access[txn].items():
                loads[key] = loads.get(key, 0) + count
                writers[key] = writers.get(key, False) or writer

        hot = {
            key: amount for key, amount in loads.items()
            if writers.get(key, False) and amount > 1
        }
        critical = max(hot.values(), default=0)
        # A transaction spanning several hot items can join their serialization
        # chains.  This bridge term distinguishes equal current-prefix costs.
        bridge = 0
        for txn in remaining:
            touched = sorted(
                (hot[key] for key in access[txn] if key in hot), reverse=True
            )
            if len(touched) > 1:
                bridge += sum(touched[1:])
        return current_cost + critical, bridge

    def ordered(records):
        """Stable structured numpy argsort, with a Python-compatible fallback."""
        if np is None:
            return sorted(records, key=lambda x: x[0])
        keys = np.array(
            [item[0] for item in records],
            dtype=[("cost", "f8"), ("rollout", "f8"),
                   ("bridge", "f8"), ("txn", "i8")],
        )
        return [records[int(i)] for i in np.argsort(keys, order=[
            "cost", "rollout", "bridge", "txn"
        ], kind="stable")]

    # Raw simulator prefix makespan remains the first key.  The rollout score
    # only breaks otherwise weak early-prefix ties in the narrow beam.
    width = max(1, min(8, num_seqs))
    beam = [((), tuple(range(n)))]
    for _ in range(n):
        expanded = []
        for prefix, remaining in beam:
            for txn in remaining:
                child = prefix + (txn,)
                rest = tuple(other for other in remaining if other != txn)
                current = cost(child)
                future, bridge = rollout(current, rest)
                expanded.append(((current, future, bridge, txn), child, rest))
        expanded = ordered(expanded)
        beam = [(prefix, remaining) for _, prefix, remaining in expanded[:width]]

    best_seq = list(min(beam, key=lambda state: cost(state[0]))[0])
    best_cost = cost(tuple(best_seq))

    # Tighten the incumbent using exact full-schedule simulator evaluations.
    for _ in range(3):
        next_seq, next_cost = best_seq, best_cost
        for source, txn in enumerate(best_seq):
            partial = best_seq[:source] + best_seq[source + 1:]
            for destination in range(n):
                candidate = tuple(partial[:destination] + [txn] + partial[destination:])
                value = cost(candidate)
                if value < next_cost:
                    next_seq, next_cost = list(candidate), value
        if next_cost >= best_cost:
            break
        best_seq, best_cost = next_seq, next_cost

    deadline = time.monotonic() + 18.0
    node_limit = 300000 if n <= 12 else 120000
    nodes = [0]

    def dfs(prefix, remaining):
        nonlocal best_cost, best_seq
        if nodes[0] >= node_limit or time.monotonic() >= deadline:
            return
        nodes[0] += 1
        lower = cost(prefix) if prefix else 0
        if lower >= best_cost:
            return
        if not remaining:
            best_cost, best_seq = lower, list(prefix)
            return

        children = []
        for txn in remaining:
            if any(other < txn and not conflicts(other, txn) for other in remaining):
                continue
            child = prefix + (txn,)
            rest = tuple(other for other in remaining if other != txn)
            current = cost(child)
            future, bridge = rollout(current, rest)
            children.append(((current, future, bridge, txn), child, rest))

        # The surrogate orders promising branches but cannot invalidate an
        # optimal branch because pruning is based solely on exact prefix cost.
        for _, child, rest in ordered(children):
            dfs(child, rest)

    dfs((), tuple(range(n)))
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
